mapper.select:
SELECT id FROM users
WHERE status = 'WITHDRAWAL_PENDING' AND purge_scheduled_at <= #{now} AND id > #{afterUserId}
ORDER BY id
LIMIT #{limit}

SELECT f.object_key FROM sheet_source_files f JOIN user_sheets s ON s.id = f.sheet_id WHERE s.user_id = #{userId}
UNION ALL
SELECT p.object_key FROM sheet_source_pages p JOIN user_sheets s ON s.id=p.sheet_id WHERE s.user_id=#{userId}

SELECT id,email FROM users
WHERE id = #{userId} AND status = 'WITHDRAWAL_PENDING' AND purge_scheduled_at <= #{now}
FOR UPDATE

mapper.delete:
DELETE e FROM evaluations e
JOIN practice_sessions s ON s.id = e.session_id
WHERE s.user_id = #{userId}
